        self.parameters = list(parameters)
        self.lr = lr
        self.beta1 = beta1
        self.beta2 = beta2
        self.eps = eps
        self.m = [self._zeros_like(parameter.data) for parameter in parameters]
        self.v = [self._zeros_like(parameter.data) for parameter in parameters]
        self.t = 0

