            raise ValueError("bias correction must be finite")
        updates = []
        for index in active:
            parameter = self.parameters[index]
            updates.append(
                (
                    index,
                    self._updated(
                        parameter.data,
                        parameter.grad,
                        self.m[index],
                        self.v[index],
                        bias1,
                        bias2,
                    ),
                )
            )
